#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/dma.h>

#define RX_BUFF_SIZE (32)
#define TX_BUFF_SIZE (32)
#define DMA_BUFF_SIZE (32)
#define HALF_DMA_BUFF_SIZE (DMA_BUFF_SIZE / 2)

static uint8_t tx_data[TX_BUFF_SIZE];
static uint8_t rx_data[RX_BUFF_SIZE];

struct dma_test_data {
	struct k_sem dma_sem;
	uint32_t channel;
	bool dma_callback_called;
	enum dma_status last_dma_status;
};

static void dma_callback(const struct device *dev, void *user_data,
			 uint32_t channel, int status)
{
	struct dma_test_data *test_data = user_data;

	test_data->dma_callback_called = true;
	test_data->last_dma_status = status;
	k_sem_give(&test_data->dma_sem);
}

static int dma_m2m_loop_test(const struct device *dev, void *data,
			     uint32_t len)
{
	struct dma_test_data *test_data = data;
	struct dma_config dma_cfg = {0};
	struct dma_block_config dma_block_cfg = {0};
	int ret;

	test_data->dma_callback_called = false;

	dma_cfg.channel_direction = MEMORY_TO_MEMORY;
	dma_cfg.source_data_size = 1;
	dma_cfg.dest_data_size = 1;
	dma_cfg.source_burst_length = 1;
	dma_cfg.dest_burst_length = 1;
	dma_cfg.dma_callback = dma_callback;
	dma_cfg.user_data = test_data;
	dma_cfg.block_count = 1;
	dma_cfg.head_block = &dma_block_cfg;
	dma_cfg.dma_slot = 0;

	dma_block_cfg.block_size = len;
	dma_block_cfg.source_address = (uint32_t)tx_data;
	dma_block_cfg.dest_address = (uint32_t)rx_data;

	ret = dma_config(dev, test_data->channel, &dma_cfg);
	if (ret != 0) {
		return ret;
	}

	ret = dma_start(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	k_sem_take(&test_data->dma_sem, K_MSEC(100));

	ret = dma_stop(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	return 0;
}

static int dma_m2m_loop_test_suspend_resume(const struct device *dev,
					    void *data, uint32_t len)
{
	struct dma_test_data *test_data = data;
	struct dma_config dma_cfg = {0};
	struct dma_block_config dma_block_cfg = {0};
	int ret;

	test_data->dma_callback_called = false;

	dma_cfg.channel_direction = MEMORY_TO_MEMORY;
	dma_cfg.source_data_size = 1;
	dma_cfg.dest_data_size = 1;
	dma_cfg.source_burst_length = 1;
	dma_cfg.dest_burst_length = 1;
	dma_cfg.dma_callback = dma_callback;
	dma_cfg.user_data = test_data;
	dma_cfg.block_count = 1;
	dma_cfg.head_block = &dma_block_cfg;
	dma_cfg.dma_slot = 0;

	dma_block_cfg.block_size = len;
	dma_block_cfg.source_address = (uint32_t)tx_data;
	dma_block_cfg.dest_address = (uint32_t)rx_data;

	ret = dma_config(dev, test_data->channel, &dma_cfg);
	if (ret != 0) {
		return ret;
	}

	ret = dma_start(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	ret = dma_suspend(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	ret = dma_resume(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	k_sem_take(&test_data->dma_sem, K_MSEC(100));

	ret = dma_stop(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	return 0;
}

static int dma_m2m_loop_test_repeated_start_stop(const struct device *dev,
						 void *data, uint32_t len)
{
	struct dma_test_data *test_data = data;
	struct dma_config dma_cfg = {0};
	struct dma_block_config dma_block_cfg = {0};
	int ret;

	test_data->dma_callback_called = false;

	dma_cfg.channel_direction = MEMORY_TO_MEMORY;
	dma_cfg.source_data_size = 1;
	dma_cfg.dest_data_size = 1;
	dma_cfg.source_burst_length = 1;
	dma_cfg.dest_burst_length = 1;
	dma_cfg.dma_callback = dma_callback;
	dma_cfg.user_data = test_data;
	dma_cfg.block_count = 1;
	dma_cfg.head_block = &dma_block_cfg;
	dma_cfg.dma_slot = 0;

	dma_block_cfg.block_size = len;
	dma_block_cfg.source_address = (uint32_t)tx_data;
	dma_block_cfg.dest_address = (uint32_t)rx_data;

	ret = dma_config(dev, test_data->channel, &dma_cfg);
	if (ret != 0) {
		return ret;
	}

	ret = dma_start(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	ret = dma_stop(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	ret = dma_start(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	k_sem_take(&test_data->dma_sem, K_MSEC(100));

	ret = dma_stop(dev, test_data->channel);
	if (ret != 0) {
		return ret;
	}

	return 0;
}

#define DMA_M2M_LOOP_TEST(dma_dev_name) \
	static struct dma_test_data dma_test_data_##dma_dev_name; \
	\
	static void dma_m2m_loop_test_##dma_dev_name##_m2m_loop_setup(void *data) \
	{ \
		struct dma_test_data *test_data = data; \
		\
		k_sem_init(&test_data->dma_sem, 0, 1); \
		\
		for (int i = 0; i < TX_BUFF_SIZE; i++) { \
			tx_data[i] = i; \
		} \
		\
		memset(rx_data, 0, sizeof(rx_data)); \
	} \
	\
	static void dma_m2m_loop_test_##dma_dev_name##_m2m_loop_teardown(void *data) \
	{ \
		struct dma_test_data *test_data = data; \
		\
		k_sem_reset(&test_data->dma_sem); \
	} \
	\
	static void dma_m2m_loop_test_##dma_dev_name##_m2m_loop(const struct device *dev, \
								void *data) \
	{ \
		struct dma_test_data *test_data = data; \
		int ret; \
		\
		ret = dma_m2m_loop_test(dev, data, DMA_BUFF_SIZE); \
		zassert_equal(ret, 0, "dma_m2m_loop_test failed"); \
		\
		zassert_true(test_data->dma_callback_called, \
			     "dma callback not called"); \
		\
		zassert_equal(test_data->last_dma_status, DMA_STATUS_COMPLETE, \
			      "dma transfer failed"); \
		\
		zassert_mem_equal(tx_data, rx_data, DMA_BUFF_SIZE, \
				  "tx_data and rx_data not equal"); \
	} \
	\
	static void dma_m2m_loop_test_##dma_dev_name##_m2m_loop_suspend_resume( \
		const struct device *dev, void *data) \
	{ \
		struct dma_test_data *test_data = data; \
		int ret; \
		\
		ret = dma_m2m_loop_test_suspend_resume(dev, data, DMA_BUFF_SIZE); \
		zassert_equal(ret, 0, "dma_m2m_loop_test_suspend_resume failed"); \
		\
		zassert_true(test_data->dma_callback_called, \
			     "dma callback not called"); \
		\
		zassert_equal(test_data->last_dma_status, DMA_STATUS_COMPLETE, \
			      "dma transfer failed"); \
		\
		zassert_mem_equal(tx_data, rx_data, DMA_BUFF_SIZE, \
				  "tx_data and rx_data not equal"); \
	} \
	\
	static void dma_m2m_loop_test_##dma_dev_name##_m2m_loop_repeated_start_stop( \
		const struct device *dev, void *data) \
	{ \
		struct dma_test_data *test_data = data; \
		int ret; \
		\
		ret = dma_m2m_loop_test_repeated_start_stop(dev, data, DMA_BUFF_SIZE); \
		zassert_equal(ret, 0, "dma_m2m_loop_test_repeated_start_stop failed"); \
		\
		zassert_true(test_data->dma_callback_called, \
			     "dma callback not called"); \
		\
		zassert_equal(test_data->last_dma_status, DMA_STATUS_COMPLETE, \
			      "dma transfer failed"); \
		\
		zassert_mem_equal(tx_data, rx_data, DMA_BUFF_SIZE, \
				  "tx_data and rx_data not equal"); \
	} \
	\
	ztest_test_suite(dma_m2m_loop_test_##dma_dev_name, \
		ztest_unit_test_pre_post_hook( \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_setup, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_teardown), \
		ztest_unit_test_pre_post_hook( \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_suspend_resume, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_setup, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_teardown), \
		ztest_unit_test_pre_post_hook( \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_repeated_start_stop, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_setup, \
			dma_m2m_loop_test_##dma_dev_name##_m2m_loop_teardown) \
	);

#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma0), okay)
DMA_M2M_LOOP_TEST(dma0);
#endif

#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma1), okay)
DMA_M2M_LOOP_TEST(dma1);
#endif

#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma2), okay)
DMA_M2M_LOOP_TEST(dma2);
#endif

static void *ztest_run_test_suite_with_device_data(const void *suite,
						   const struct device *dev,
						   void *user_data)
{
	const struct ztest_suite_node *const suite_node = suite;
	struct ztest_unit_test *test;
	int count = 0;
	void *ret = NULL;

	if (suite_node->pre_fn != NULL) {
		suite_node->pre_fn(suite_node->data);
	}

	for (int i = 0; i < suite_node->test_count; i++) {
		test = &suite_node->tests[i];
		ztest_test_c_start(test);
		TC_START(test->name);
		ztest_set_test_phase(ZTEST_PHASE_TEST);
		if (test->pre_fn != NULL) {
			test->pre_fn(user_data);
		}
		((void (*)(const struct device *, void *))test->test)(dev, user_data);
		if (test->post_fn != NULL) {
			test->post_fn(user_data);
		}
		ztest_test_pass();
		ztest_set_test_phase(ZTEST_PHASE_FRAMEWORK);
		TC_END(test->name, ztest_get_err_count() > count ? FAIL : PASS,
		       "");
		count = ztest_get_err_count();
	}

	if (suite_node->post_fn != NULL) {
		suite_node->post_fn(suite_node->data);
	}

	return ret;
}

void test_main(void)
{
#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma0), okay)
	const struct device *dma0_dev = DEVICE_DT_GET(DT_NODELABEL(dma0));

	dma_test_data_dma0.channel = 0;
	ztest_run_test_suite_with_device_data(&dma_m2m_loop_test_dma0, dma0_dev,
					      &dma_test_data_dma0);
#endif

#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma1), okay)
	const struct device *dma1_dev = DEVICE_DT_GET(DT_NODELABEL(dma1));

	dma_test_data_dma1.channel = 0;
	ztest_run_test_suite_with_device_data(&dma_m2m_loop_test_dma1, dma1_dev,
					      &dma_test_data_dma1);
#endif

#if DT_NODE_HAS_STATUS(DT_NODELABEL(dma2), okay)
	const struct device *dma2_dev = DEVICE_DT_GET(DT_NODELABEL(dma2));

	dma_test_data_dma2.channel = 0;
	ztest_run_test_suite_with_device_data(&dma_m2m_loop_test_dma2, dma2_dev,
					      &dma_test_data_dma2);
#endif
}
